using System;
using System.Collections.Generic;
using System.Linq;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Controls.ApplicationLifetimes;
using Avalonia.Interactivity;
using Avalonia.Platform;
using Avalonia.Threading;

namespace Noctis.Services;

/// <summary>
/// Alternate app icons (Settings › Appearance › App Icon). Holds the chosen icon and puts it
/// on every window (title bar + taskbar button) and the tray, live. The exe/shortcut icon is
/// a Win32 resource baked in at build time and stays the classic one.
/// Icons live in Assets/AppIcons (generated by scripts/app-icons/generate_app_icons.py).
/// </summary>
public static class AppIconService
{
    public const string DefaultId = "classic";

    /// <summary>Ids in display order; each has Assets/AppIcons/&lt;id&gt;.ico and .png.</summary>
    public static IReadOnlyList<string> Ids { get; } = new[]
    {
        "classic", "dark", "blush", "sky", "sunset", "violet", "aurora",
        "midnight", "graphite", "ruby", "neon",
    };

    private static readonly Dictionary<string, WindowIcon> s_cache = new(StringComparer.Ordinal);
    private static readonly List<Window> s_open = new();
    private static bool s_attached;

    public static string CurrentId { get; private set; } = DefaultId;

    /// <summary>Raised on the UI thread after <see cref="CurrentId"/> changed (tray follows it).</summary>
    public static event EventHandler? Changed;

    /// <summary>Unknown/empty ids (an older or hand-edited settings file) fall back to classic.</summary>
    public static string Normalize(string? id)
    {
        if (string.IsNullOrWhiteSpace(id)) return DefaultId;
        var trimmed = id.Trim();
        return Ids.FirstOrDefault(x => string.Equals(x, trimmed, StringComparison.OrdinalIgnoreCase)) ?? DefaultId;
    }

    public static string IconUri(string id) => $"avares://Noctis/Assets/AppIcons/{Normalize(id)}.ico";

    public static string PreviewUri(string id) => $"avares://Noctis/Assets/AppIcons/{Normalize(id)}.png";

    /// <summary>The chosen icon, or null when no Avalonia platform can load icons (plain unit tests).</summary>
    public static WindowIcon? CurrentIcon => Load(CurrentId);

    public static WindowIcon? Load(string id)
    {
        id = Normalize(id);
        if (s_cache.TryGetValue(id, out var cached)) return cached;
        try
        {
            using var stream = AssetLoader.Open(new Uri(IconUri(id)));
            var icon = new WindowIcon(stream);
            s_cache[id] = icon;
            return icon;
        }
        catch (Exception ex)
        {
            DebugLogger.Error(DebugLogger.Category.UI, "AppIcon.Load", $"{id}: {ex.Message}");
            return null;
        }
    }

    /// <summary>
    /// Once at startup: every window that opens from now on (mini player, dialogs, tool
    /// windows) gets the chosen icon, so a dialog's taskbar button never shows a stale one.
    /// </summary>
    public static void Attach()
    {
        if (s_attached) return;
        s_attached = true;
        Window.WindowOpenedEvent.AddClassHandler<Window>((w, _) =>
        {
            if (!s_open.Contains(w)) s_open.Add(w);
            ApplyTo(w);
        }, RoutingStrategies.Direct, handledEventsToo: true);
        Window.WindowClosedEvent.AddClassHandler<Window>((w, _) => s_open.Remove(w),
            RoutingStrategies.Direct, handledEventsToo: true);
    }

    /// <summary>Selects an icon and repaints every open window with it.</summary>
    public static void Apply(string? id)
    {
        var next = Normalize(id);
        if (!Dispatcher.UIThread.CheckAccess())
        {
            Dispatcher.UIThread.Post(() => Apply(next));
            return;
        }
        var changed = next != CurrentId;
        CurrentId = next;
        IEnumerable<Window> windows = s_open.ToArray();
        if (Application.Current?.ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)
            windows = windows.Union(desktop.Windows.ToArray());
        foreach (var w in windows)
            ApplyTo(w);
        if (changed) Changed?.Invoke(null, EventArgs.Empty);
    }

    internal static void ApplyTo(Window w)
    {
        var icon = CurrentIcon;
        if (icon != null && !ReferenceEquals(w.Icon, icon))
            w.Icon = icon;
    }
}
